WITH enriched AS (SELECT *, MAX(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_max_rating, AVG(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_rating, MIN(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_rating, PERCENT_RANK() OVER (PARTITION BY city ORDER BY rating DESC NULLS FIRST) rating_percent_rank FROM suppliers), with_windows AS (SELECT id, supplier_name, city, rating, running_max_rating, LAG(running_max_rating) OVER (PARTITION BY country ORDER BY rating, id) prev_running_max_rating, LAG(running_min_rating) OVER (PARTITION BY country ORDER BY rating, id) prev_running_min_rating, ROW_NUMBER() OVER (PARTITION BY country ORDER BY rating, id) event_seq FROM enriched WHERE city = 'Bangkok'), base AS (SELECT *, FLOOR(running_max_rating) running_max_rating_whole FROM with_windows WHERE prev_running_max_rating < 2.7), not_flagged AS (SELECT s.* FROM base s WHERE NOT EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND c.price <= 410)), eligible AS (SELECT s.* FROM not_flagged s WHERE EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.stock_qty != 291)), with_latest AS (SELECT s.*, x.cost FROM eligible s JOIN LATERAL (SELECT c.cost FROM products c WHERE c.supplier_id = s.id ORDER BY c.price DESC, c.id DESC LIMIT 1) x ON TRUE), latest_match AS (SELECT s.id, s.supplier_name, s.city, s.prev_running_max_rating, s.prev_running_min_rating, s.running_max_rating_whole, s.cost, x.product_cost FROM with_latest s LEFT JOIN LATERAL (SELECT c.cost AS product_cost FROM products c WHERE c.supplier_id = s.id ORDER BY c.stock_qty DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, city, running_max_rating_whole, cost FROM latest_match ORDER BY cost;
